#include "word_core.hpp"
int main(int argc,char**argv){if(argc<9){cerr<<"input.poly projected.cert endpoints weight max context outputprefix output.poly\n";return 2;}string input=argv[1],certfile=argv[2],endfile=argv[3],pref=argv[7],output=argv[8];int n=stoi(argv[4]),m=stoi(argv[5]);U context=stoull(argv[6]);auto start=chrono::steady_clock::now();auto sec=[&](){return chrono::duration<double>(chrono::steady_clock::now()-start).count();};QP r=read_poly(input);PolyWord p;Fib f;map<pair<int,int>,QP>endpoints;
 {ifstream in(endfile);int n,bs;string co;while(in>>n>>bs>>co){vector<int>w(n);for(int&a:w)in>>a;mpq_class c(co);c.canonicalize();for(auto[k,d]:p.get(makew(w)))qadd(endpoints[{n,bs}],k,c*d);}}
 ifstream in(certfile);ofstream certout(pref+".full.certificate.txt");string co;int count=0;while(in>>co){U oldctx;in>>oldctx;if(oldctx)throw runtime_error("projected certificate context");U sc=read_label(in);QP source;for(auto[w,c]:raw_source(sc,f))for(auto[k,d]:p.get(w))qadd(source,k,mpq_class(c*d));if(!scaling_source(sc)){auto a=affdecode(sc);int bs=0;for(auto t:a)bs=bs*2+t.b;for(auto[k,c]:endpoints[{(int)a.size(),bs}])qadd(source,k,-c);}mpq_class c(co);c.canonicalize();qmuladd(r,source,context,-c,true);certout<<c<<" "<<context<<" ";write_label(certout,sc);certout<<"\n";if(++count%5000==0)cerr<<"POLY APPLY "<<count<<" terms="<<r.size()<<" sec="<<sec()<<"\n";}
 int residual=0;for(auto[k,c]:r){auto a=monvec(k);for(int j=0;j<(int)a.size();j++)if(wn(a[j])==n&&maxw(a[j])==m){auto rest=a;rest.erase(rest.begin()+j);if(moncode(rest)==context)residual++;}}
 cerr<<"EXACT POLY PROJECTION weight="<<n<<" max="<<m<<" context="<<context<<" residual="<<residual<<" cert="<<count<<" sec="<<sec()<<"\n";
 if(residual)return 1;save_poly(output,r);ofstream report(pref+".report.json");report<<"{\"factor_weight\":"<<n<<",\"max_letter\":"<<m<<",\"context\":\""<<context<<"\",\"certificate_rows\":"<<count<<",\"residual_projected_terms\":0,\"remaining_polynomial_terms\":"<<r.size()<<",\"seconds\":"<<sec()<<"}\n";return 0;
}
